import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/consts'
import type {PopupAttrs} from '@jetbrains/ring-ui-built/components/popup/popup'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import * as React from 'react'

import PopupMenu from '../Popup/PopupMenu'

import styles from './ArrowPopupMenu.module.css'

type Props = {
  className?: string
  anchorClassName?: string
  icon?: string
  title?: string
  elements: ReadonlyArray<ListDataItem> | null | undefined
  directions?: PopupAttrs['directions']
}

function ArrowPopupMenu({
  className,
  anchorClassName,
  title = '',
  elements,
  icon,
  directions,
}: Props): React.ReactNode {
  const onClick = React.useCallback((event: React.SyntheticEvent) => {
    event.stopPropagation()
    event.preventDefault()
  }, [])

  if (elements == null || elements.length === 0) {
    return null
  }

  const anchor = (
    <IconButton
      className={classNames(styles.anchor, anchorClassName)}
      title={title}
      aria-label={title || 'Actions'}
      icon={icon != null ? icon : 'more-options'}
    />
  )

  return (
    <span
      className={classNames(styles.arrowPopupMenu, className)}
      role="presentation"
      onClick={onClick}
    >
      <Dropdown anchor={anchor} hoverMode>
        <PopupMenu data={elements} closeOnSelect directions={directions} />
      </Dropdown>
    </span>
  )
}

export default React.memo(ArrowPopupMenu)
