import {memo, Suspense, useCallback} from 'react'

import {getBuildType} from '../../../selectors'
import {restApi} from '../../../services/rest'
import type {BuildId, TestOccurrenceId} from '../../../types'
import {assignTestInvestigations} from '../../packages/Tests/Tests.actions'
import {getTestOccurenceArg} from '../../packages/Tests/Tests.rest'
import {
  getFlakyTestData,
  getTestOccurrence,
  getTestOccurrenceCurrentlyMutes,
  getTestOccurrenceMute,
} from '../../packages/Tests/Tests.selectors'

import Mutes from './Mutes'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

type Props = {
  className?: string
  iconClassName?: string
  buildId: BuildId | null | undefined
  testOccurrenceId?: TestOccurrenceId
}

function TestMutes({className, iconClassName, testOccurrenceId, buildId}: Props) {
  const dispatch = useAppDispatch()

  const testOccurrence = useAppSelector(state => getTestOccurrence(state, testOccurrenceId))
  const {build, test, currentlyMuted} = testOccurrence ?? {}
  const {buildTypeId} = build ?? {}
  const {id: testId} = test ?? {}
  const {isFlaky} = useAppSelector(state => getFlakyTestData(state, buildId, testId)) ?? {}
  const {projectId} = useAppSelector(state => getBuildType(state, buildTypeId)) ?? {}

  const mute = useAppSelector(state => getTestOccurrenceMute(state, testOccurrenceId))
  const currentlyMutes = useAppSelector(state =>
    getTestOccurrenceCurrentlyMutes(state, testOccurrenceId),
  )

  const [fetchTestOccurrence] =
    restApi.endpoints.getTestOccurrenceNormalized.useLazyQuerySubscription()
  const muteHandler = useCallback(() => {
    if (projectId != null && buildId != null && testId != null) {
      const submitHandler = () =>
        testOccurrenceId != null &&
        fetchTestOccurrence(
          getTestOccurenceArg(testOccurrenceId, {
            withNewFailure: true,
            withMetadataCount: true,
            withNextFixed: true,
            withFirstFailed: true,
            withMuteInfo: true,
            withInvestigationInfo: true,
          }),
        )
      dispatch(
        assignTestInvestigations(
          projectId,
          [testId],
          isFlaky ? [testId] : [],
          [buildId],
          true,
          submitHandler,
        ),
      )
    }
  }, [projectId, buildId, testId, dispatch, isFlaky, testOccurrenceId, fetchTestOccurrence])
  return (
    <Suspense>
      <Mutes
        className={className}
        iconClassName={iconClassName}
        projectId={projectId}
        buildTypeId={buildTypeId}
        currentlyMuted={currentlyMuted}
        mute={mute}
        currentlyMutes={currentlyMutes}
        muteHandler={muteHandler}
      />
    </Suspense>
  )
}

export default memo(TestMutes)
