import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import type {ReactNode} from 'react'
import {memo, Suspense, useCallback, useMemo} from 'react'

import {useIsAutodetectTimeZone} from '../../../hooks/useIsAutodetectTimeZone'
import {useIsHighlightMyChangesAndInvestigations} from '../../../hooks/useIsHighlightMyChangesAndInvestigations'
import useMyId from '../../../hooks/useMyId'
import {usePermission} from '../../../hooks/usePermission'
import {getProjectsHash} from '../../../selectors'
import type {BuildTypeId, Investigation, ProjectId} from '../../../types'
import {InvestigationStates, Permission, stringifyId} from '../../../types'
import {emptyArray, noop} from '../../../utils/empty'
import Avatar, {Size} from '../Avatar/Avatar.container'
import Badge from '../Badge/Badge'
import Icon from '../Icon/Icon'
import Popup from '../Popup/Popup.lazy'

import InvestigationDetails from './InvestigationDetails'
import {getInvestigationInCurrentScope} from './Investigations.selectors'
import {getActiveInvestigations, getAssigneeName, getFilteredEntities} from './Investigations.utils'

import styles from './Investigations.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

const directions = [
  Directions.BOTTOM_RIGHT,
  Directions.TOP_RIGHT,
  Directions.BOTTOM_LEFT,
  Directions.TOP_LEFT,
]

type Props = {
  className?: string
  iconClassName?: string
  projectId: ProjectId | null | undefined
  buildTypeId: BuildTypeId | null | undefined
  currentlyInvestigated: boolean | null | undefined
  readonly investigations: ReadonlyArray<Investigation>
  isShowOnlyIcon?: boolean
  isBadge?: boolean
  onAssignInvestigation?: (presetFix?: boolean) => unknown
  onShowInvestigationHistory?: () => unknown
}

type ContainerProps = {
  isHighlightMyInvestigations: boolean
  isAutodetectTimeZone: boolean
}

function InvestigationsComponent({
  className,
  iconClassName,
  projectId,
  buildTypeId,
  currentlyInvestigated,
  investigations = emptyArray,
  isShowOnlyIcon = false,
  isBadge = false,
  onAssignInvestigation = noop,
  onShowInvestigationHistory,
  isHighlightMyInvestigations,
  isAutodetectTimeZone,
}: Props & ContainerProps) {
  const currentUserId = useMyId()
  const hasPermission = usePermission(Permission.ASSIGN_INVESTIGATION, projectId)

  const handleAssignInvestigation = useCallback(
    () => onAssignInvestigation(),
    [onAssignInvestigation],
  )
  const handleFixInvestigation = useCallback(
    () => onAssignInvestigation(true),
    [onAssignInvestigation],
  )
  const getIsAssignedToCurrentUser = useCallback(
    (investigation: Investigation) => investigation.assignee.id === currentUserId,
    [currentUserId],
  )
  const activeInvestigations = useMemo(
    () => getActiveInvestigations(investigations),
    [investigations],
  )
  const projectsHash = useAppSelector(getProjectsHash)
  const investigationInCurrentScope = useAppSelector(state =>
    getInvestigationInCurrentScope(state, activeInvestigations, projectId, buildTypeId),
  )
  const filteredInvestigations = useMemo(
    () => getFilteredEntities(projectsHash, activeInvestigations, projectId, buildTypeId),
    [buildTypeId, activeInvestigations, projectId, projectsHash],
  )
  const {state} = investigationInCurrentScope ?? {}
  const popup = useMemo(
    () => (
      <Popup
        className={classNames(styles.popup, {
          [styles.hasPermission]: hasPermission,
          [styles.withSeveralInvestigations]: filteredInvestigations.length > 1,
        })}
        directions={directions}
      >
        <div data-test-investigation-popup className={styles.body}>
          <div className={styles.content}>
            {filteredInvestigations.map(item => (
              <div key={stringifyId(item.id)} className={styles.investigationDetails}>
                <InvestigationDetails
                  buildTypeId={buildTypeId}
                  currentUserId={currentUserId}
                  investigation={item}
                  isAutodetectTimeZone={isAutodetectTimeZone}
                />
              </div>
            ))}
          </div>
          {hasPermission && (
            <div className={styles.footer}>
              <Button className={styles.actionButton} onClick={handleAssignInvestigation}>
                {'Reassign...'}
              </Button>
              {state !== InvestigationStates.FIXED && (
                <Button className={styles.actionButton} onClick={handleFixInvestigation}>
                  {'Fix...'}
                </Button>
              )}
              {onShowInvestigationHistory != null && (
                <Button className={styles.actionButton} onClick={onShowInvestigationHistory}>
                  {'Show history'}
                </Button>
              )}
            </div>
          )}
        </div>
      </Popup>
    ),
    [
      buildTypeId,
      currentUserId,
      filteredInvestigations,
      handleAssignInvestigation,
      handleFixInvestigation,
      hasPermission,
      isAutodetectTimeZone,
      onShowInvestigationHistory,
      state,
    ],
  )

  const renderContent = useCallback(
    (content: ReactNode, onClick?: () => void) => (
      <>
        {isBadge ? (
          <Badge
            dataTestId={'investigations-badge'}
            className={styles.badgeContainer}
            labelClassName={styles.label}
            label={state === InvestigationStates.FIXED ? 'Investigation fixed' : 'Investigation'}
            onClick={onClick}
            clickable
          >
            {content}
          </Badge>
        ) : (
          content
        )}
      </>
    ),
    [isBadge, state],
  )

  const emptyInvestigation = useMemo(
    () => (
      <div className={classNames(className, styles.wrapper)} data-test-investigation>
        <IconButton
          className={styles.assignAction}
          iconClassName={classNames(styles.icon, {[styles.badge]: isBadge})}
          icon={isBadge ? 'investigation-12px' : 'investigation'}
          title=""
          onClick={handleAssignInvestigation}
        >
          <span className={classNames(styles.emptyText, {[styles.badge]: isBadge})}>
            {isBadge ? 'No assignee' : 'Assign investigation...'}
          </span>
        </IconButton>
      </div>
    ),
    [className, handleAssignInvestigation, isBadge],
  )

  if (investigationInCurrentScope == null && hasPermission && isShowOnlyIcon === false) {
    return renderContent(emptyInvestigation, handleAssignInvestigation)
  }

  if (currentlyInvestigated === true || state === InvestigationStates.FIXED) {
    if (investigationInCurrentScope == null) {
      return null
    }

    const isAssignedToCurrentUser = getIsAssignedToCurrentUser(investigationInCurrentScope)
    const assigneeName = getAssigneeName(
      investigationInCurrentScope,
      isAssignedToCurrentUser,
      isBadge,
    )
    const user = investigationInCurrentScope.assignee
    let content = isBadge ? assigneeName : `Investigation assigned to ${assigneeName}`

    if (state === InvestigationStates.FIXED) {
      content = isBadge ? assigneeName : `Investigation fixed by ${assigneeName}`
    }

    const iconClasses = classNames(iconClassName, styles.icon, {
      [styles.assignedToMe]:
        state === InvestigationStates.TAKEN &&
        isAssignedToCurrentUser &&
        isHighlightMyInvestigations,
      [styles.fixed]: state === InvestigationStates.FIXED,
      [styles.badge]: isBadge,
    })
    const anchor = (
      <Button
        className={classNames(styles.anchor, {[styles.badge]: isBadge})}
        aria-label="investigation"
        inline
      >
        <div className={classNames(styles.anchorContent, {[styles.badge]: isBadge})}>
          {isBadge ? (
            <Avatar user={user} size={Size.Size20} />
          ) : (
            <Icon className={iconClasses} name={'investigation'} />
          )}
          {isShowOnlyIcon !== true && (
            <>
              <span className={styles.anchorText}>
                {investigations.length === 1 ? content : 'Investigations'}
              </span>
              <Icon className={styles.anchorChevron} name="chevron-12px-down" />
            </>
          )}
        </div>
      </Button>
    )
    return (
      <div className={classNames(className, styles.wrapper)} data-test-investigation>
        <Dropdown className={styles.dropdown} anchor={renderContent(anchor)} hoverMode={!isBadge}>
          {popup}
        </Dropdown>
      </div>
    )
  }

  return null
}

const Investigations = memo(InvestigationsComponent)

function InvestigationsContainer(props: Props) {
  const isHighlightMyInvestigations = useIsHighlightMyChangesAndInvestigations()
  const isAutodetectTimeZone = useIsAutodetectTimeZone()

  return (
    <Suspense>
      <Investigations
        {...props}
        isHighlightMyInvestigations={isHighlightMyInvestigations}
        isAutodetectTimeZone={isAutodetectTimeZone}
      />
    </Suspense>
  )
}

export default memo(InvestigationsContainer)
