import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/consts'
import List from '@jetbrains/ring-ui-built/components/list/list'
import {memo, Suspense, useCallback, useContext, useMemo} from 'react'
import {useLinkClickHandler, useLocation, useNavigate} from 'react-router'

import {openDialog} from '../../../../actions'
import {usePermission} from '../../../../hooks/usePermission'
import {getHrefWithQueryParams, getTestHistoryHref} from '../../../../routes'
import {getBuild, getBuildType, getPipeline, getPipelineIdFromBuildId} from '../../../../selectors'
import {restApi} from '../../../../services/rest'
import type {BuildId, ProjectId, TestOccurrenceId} from '../../../../types'
import {DialogType, InvestigationStates, Permission, stringifyId} from '../../../../types'
import {BS} from '../../../../types/BS_types'
import {emptyArray} from '../../../../utils/empty'
import ArrowPopupMenu from '../../../common/ArrowPopupMenu/ArrowPopupMenu'
import {getInvestigationInCurrentScope} from '../../../common/Investigations/Investigations.selectors'
import {PipelinesTargetContext} from '../../../pages/PipelinesPages/contexts/targetContext'
import {getFullBuildLogLinkParams} from '../../BuildLog/BuildLog.utils'
import {assignTestInvestigations} from '../Tests.actions'
import {getTestOccurenceArg} from '../Tests.rest'
import {getFlakyTestData, getTestOccurrence} from '../Tests.selectors'
import {TestStatus} from '../Tests.types'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

type Props = {
  className?: string
  anchorClassName?: string
  buildId: BuildId | null | undefined
  testOccurrenceId?: TestOccurrenceId
}

function BuildTestActions({className, anchorClassName, buildId, testOccurrenceId}: Props) {
  const pipelinesTarget = useContext(PipelinesTargetContext)
  const dispatch = useAppDispatch()
  const location = useLocation()
  const navigate = useNavigate()

  const build = useAppSelector(state => getBuild(state, buildId))
  const buildType = useAppSelector(state => getBuildType(state, build?.buildType))
  const testOccurrence = useAppSelector(state => getTestOccurrence(state, testOccurrenceId))
  const pipelineId = useAppSelector(state => getPipelineIdFromBuildId(state, buildId))
  const pipelineParentProject = useAppSelector(
    state => getPipeline(state, pipelineId)?.parentProject,
  )

  const {
    test,
    status,
    logAnchor,
    currentlyMuted,
    build: testBuild,
    currentlyInvestigated,
  } = testOccurrence ?? {}

  const testId = test?.id
  const {id: testBuildId, buildType: testBuildType} = testBuild ?? {}
  const testProject = testBuildType?.project
  const testProjectId: ProjectId | undefined = pipelineParentProject?.id ?? testProject?.id
  const investigations = test?.investigations?.investigation ?? emptyArray

  const investigationInCurrentScope = useAppSelector(state =>
    getInvestigationInCurrentScope(state, investigations, buildType?.projectId, buildType?.id),
  )
  const isFlakyTest =
    useAppSelector(state => getFlakyTestData(state, buildId, testId)?.isFlaky) ?? false

  const hasPermissionForInvestigation = usePermission(
    Permission.ASSIGN_INVESTIGATION,
    testProjectId,
  )
  const hasPermissionForManageProblems = usePermission(
    Permission.MANAGE_BUILD_PROBLEMS,
    testProjectId,
  )

  const [fetchTestOccurrence] =
    restApi.endpoints.getTestOccurrenceNormalized.useLazyQuerySubscription()
  const assignInvestigationHandler = useCallback(
    (presetFix = false) => {
      if (testId != null && testBuildId && testProjectId != null) {
        const submitHandler = () =>
          testOccurrenceId != null &&
          fetchTestOccurrence(
            getTestOccurenceArg(testOccurrenceId, {
              withNewFailure: true,
              withMetadataCount: true,
              withNextFixed: true,
              withFirstFailed: true,
              withMuteInfo: true,
              withInvestigationInfo: true,
            }),
          )
        dispatch(
          assignTestInvestigations(
            testProjectId,
            [testId],
            isFlakyTest ? [testId] : [],
            [testBuildId],
            presetFix,
            submitHandler,
          ),
        )
      }
    },
    [
      testId,
      testBuildId,
      testProjectId,
      dispatch,
      isFlakyTest,
      testOccurrenceId,
      fetchTestOccurrence,
    ],
  )

  const onAssignInvestigation = useCallback(
    () => assignInvestigationHandler(),
    [assignInvestigationHandler],
  )
  const onFixInvestigation = useCallback(
    () => assignInvestigationHandler(true),
    [assignInvestigationHandler],
  )
  const onShowInvestigationHistory = useCallback(
    () => dispatch(openDialog(stringifyId(testId), DialogType.INVESTIGATION_HISTORY)),
    [dispatch, testId],
  )
  const onOpenInIDE = useCallback(
    () =>
      logAnchor != null &&
      BS?.Activator?.doOpen(`test?buildId=${stringifyId(testBuildId)}&testId=${logAnchor}`),
    [logAnchor, testBuildId],
  )
  const onShowInBuildLog = useCallback(
    () =>
      testBuildId != null
        ? navigate(
            getHrefWithQueryParams(location, null, params => ({
              ...params,
              ...getFullBuildLogLinkParams({
                buildId: testBuildId,
                line: logAnchor,
                expandState: [Number(logAnchor)],
                logFilter: 'debug',
              }),
            })),
            {preventScrollReset: true},
          )
        : null,
    [testBuildId, location, logAnchor, navigate],
  )
  const testHistoryHref = getTestHistoryHref(testId, {
    currentPipelineId: pipelineId,
    currentProjectId: stringifyId(testProjectId),
  })
  const testHistoryClickHandler = useLinkClickHandler(testHistoryHref)

  return useMemo(() => {
    const elements: ListDataItem[] = []

    if (pipelinesTarget == null) {
      elements.push({
        key: 'testHistory',
        href: testHistoryHref,
        onClick: (_, e) => testHistoryClickHandler(e as React.MouseEvent<HTMLAnchorElement>),
        label: 'Show test history',
      })

      elements.push({
        rgItemType: List.ListProps.Type.ITEM,
        title: '',
        label: 'Show investigation history',
        onClick: onShowInvestigationHistory,
      })

      if (hasPermissionForInvestigation) {
        elements.push({
          rgItemType: List.ListProps.Type.ITEM,
          title: '',
          label:
            currentlyInvestigated === true ||
            investigationInCurrentScope?.state === InvestigationStates.FIXED
              ? 'Reassign investigation...'
              : 'Assign investigation...',
          onClick: onAssignInvestigation,
        })

        if (
          currentlyInvestigated === true &&
          investigationInCurrentScope?.state !== InvestigationStates.FIXED
        ) {
          elements.push({
            rgItemType: List.ListProps.Type.ITEM,
            title: '',
            label: 'Fix investigation...',
            onClick: onFixInvestigation,
          })
        }
      }

      if (hasPermissionForManageProblems) {
        elements.push({
          rgItemType: List.ListProps.Type.ITEM,
          title: '',
          label: currentlyMuted === true ? 'Unmute test...' : 'Mute test...',
          onClick: onAssignInvestigation,
        })
      }
    }

    if (status === TestStatus.FAILURE && logAnchor != null) {
      elements.push({
        rgItemType: List.ListProps.Type.ITEM,
        title: '',
        label: 'Open in IDE',
        onClick: onOpenInIDE,
      })
    }

    if (testBuildId != null && Number(logAnchor) != null) {
      elements.push({
        rgItemType: List.ListProps.Type.ITEM,
        title: '',
        label: 'Show in build log',
        onClick: onShowInBuildLog,
      })
    }

    return (
      <ArrowPopupMenu className={className} anchorClassName={anchorClassName} elements={elements} />
    )
  }, [
    pipelinesTarget,
    status,
    logAnchor,
    testBuildId,
    className,
    anchorClassName,
    testHistoryHref,
    testHistoryClickHandler,
    onShowInvestigationHistory,
    hasPermissionForInvestigation,
    hasPermissionForManageProblems,
    currentlyInvestigated,
    investigationInCurrentScope?.state,
    onAssignInvestigation,
    onFixInvestigation,
    currentlyMuted,
    onOpenInIDE,
    onShowInBuildLog,
  ])
}

function BuildTestActionsContainer(props: Props) {
  return (
    <Suspense>
      <BuildTestActions {...props} />
    </Suspense>
  )
}

export default memo(BuildTestActionsContainer)
